const D = { energy: .6, scale: 1, speed: 1, density: .5, peclet: .6, feed: .036, kill: .062, hue: 172, x: .5, y: .5, style: 'chemical', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Reaction-ADVECTION: Gray-Scott chemistry running inside a moving fluid. Every step the
// reagents are semi-Lagrangian-advected along a divergence-free curl field before they react,
// so the Turing spots never sit still — they are stretched into comet filaments, sheared,
// folded and torn, and re-nucleate downstream. At Peclet ~0 it collapses to ordinary
// Gray-Scott; the whole identity of the piece lives at HIGH Peclet. ----
const BW = 168, BH = Math.max(72, Math.round(BW * height / width));
