}
function fbm3(x, y, z) { return 0.57 * vn3(x, y, z) + 0.28 * vn3(x * 2.05 + 5.1, y * 2.05 - 3.2, z * 1.6 + 1.3) + 0.15 * vn3(x * 4.11 - 2.3, y * 4.11 + 7.7, z * 2.7 - 4.1); }

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  S.U.fill(1); S.V.fill(0);
  for (let b = 0; b < 26; b++) {
    const cx = hsh(b * 3 + 1, 1, 3) * BW, cy = hsh(b * 3 + 2, 2, 3) * BH;
    const rad = 2 + hsh(b * 3 + 3, 4, 3) * 4;
    const r2 = rad * rad;
    for (let j = Math.max(0, (cy - rad) | 0); j <= Math.min(BH - 1, (cy + rad) | 0); j++)
      for (let i = Math.max(0, (cx - rad) | 0); i <= Math.min(BW - 1, (cx + rad) | 0); i++) {
        const dx = i - cx, dy = j - cy;
        if (dx * dx + dy * dy > r2) continue;
        S.U[j * BW + i] = 0.5; S.V[j * BW + i] = 0.28;
