}

const tt = K.t;
const sp = 0.3 + P.speed * 0.9;
const U = S.U, V = S.V, U2 = S.U2, V2 = S.V2, VX = S.VX, VY = S.VY, PS = S.PS;

// ---- the flow: curl of a drifting stream function (incompressible). psi to a grid, then
// difference the grid — a per-cell finite difference would cost 4x the fbm evals. ----
const zf = tt * 0.061 * sp + 4.1;
const ox = 1.5 * Math.sin(tt * 0.043) + 0.7 * Math.sin(tt * 0.107 + 1.7);
const oy = 1.2 * Math.cos(tt * 0.067) + 0.55 * Math.sin(tt * 0.139 + 0.5);
const fs = 2.2 / BH;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) PS[j * BW + i] = fbm3(i * fs + ox, j * fs + oy, zf);
// Peclet: advective transport vs diffusive. High = long comet filaments.
const pe = (0.06 + P.peclet * 1.05) * sp;
const swirl = 0.30 * Math.sin(tt * 0.0233 + 1.1);   // slow global rotation, incommensurate
for (let j = 0; j < BH; j++) {
  const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
  const ry = (j / BH - P.y);
  for (let i = 0; i < BW; i++) {
    const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
    const rx = (i / BW - P.x);
    VX[jc + i] = ((PS[jp + i] - PS[jm + i]) * 26 - ry * swirl * 5.5) * pe;
    VY[jc + i] = (-(PS[jc + ip] - PS[jc + im]) * 26 + rx * swirl * 5.5) * pe;
  }
}

// ---- feed/kill march slowly on incommensurate sines: the chemistry walks through regimes
// (spots -> worms -> maze -> mitosis) over minutes ----
const fk = 0.006 * Math.sin(tt * 0.0197) + 0.003 * Math.sin(tt * 0.0431 + 1.6);
const F = Math.max(0.008, Math.min(0.09, P.feed + fk + A.bass * 0.004));
const KL = Math.max(0.03, Math.min(0.073, P.kill + 0.0035 * Math.sin(tt * 0.0263 + 0.8)));
const Du = 0.16, Dv = 0.08;
const steps = Math.max(1, Math.min(4, Math.round(1 + P.speed * 1.2)));

for (let st = 0; st < steps; st++) {
  // (1) advect both reagents along the flow (semi-Lagrangian, periodic)
  for (let j = 0; j < BH; j++) {
    const jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const p = jc + i;
      let bx = i - VX[p], by = j - VY[p];
      bx = ((bx % BW) + BW) % BW; by = ((by % BH) + BH) % BH;
      const x0 = bx | 0, y0 = by | 0, fx = bx - x0, fy = by - y0;
      const x1 = (x0 + 1) % BW, y1 = (y0 + 1) % BH;
      const ua = U[y0 * BW + x0], ub = U[y0 * BW + x1], uc = U[y1 * BW + x0], ud = U[y1 * BW + x1];
      const va = V[y0 * BW + x0], vb = V[y0 * BW + x1], vc = V[y1 * BW + x0], vd = V[y1 * BW + x1];
      const ut = ua + (ub - ua) * fx, ubt = uc + (ud - uc) * fx;
      const vt = va + (vb - va) * fx, vbt = vc + (vd - vc) * fx;
      U2[p] = ut + (ubt - ut) * fy;
      V2[p] = vt + (vbt - vt) * fy;
    }
  }
  // (2) react + diffuse
  for (let j = 0; j < BH; j++) {
    const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
      const p = jc + i;
      const u = U2[p], v = V2[p];
      const lu = U2[jc + im] + U2[jc + ip] + U2[jm + i] + U2[jp + i] - 4 * u;
      const lv = V2[jc + im] + V2[jc + ip] + V2[jm + i] + V2[jp + i] - 4 * v;
      const uvv = u * v * v;
      let nu = u + (Du * lu - uvv + F * (1 - u));
      let nv = v + (Dv * lv + uvv - (F + KL) * v);
      U[p] = nu < 0 ? 0 : (nu > 1.4 ? 1.4 : nu);
      V[p] = nv < 0 ? 0 : (nv > 1.4 ? 1.4 : nv);
    }
  }
}

// ---- perpetual nucleation: a few drifting injectors keep seeding fresh reagent, so the
// chemistry never dies out or settles into a fixed frame ----
const nInj = 1 + Math.round(P.density * 4);
for (let s = 0; s < nInj; s++) {
  const a1 = 0.21 + hsh(s * 7 + 1, 2, 8) * 0.5, a2 = 0.19 + hsh(s * 7 + 2, 3, 8) * 0.46;
  const cx = (0.5 + 0.40 * Math.sin(tt * a1 * 0.27 + hsh(s, 5, 8) * 6.28)) * BW;
  const cy = (0.5 + 0.38 * Math.cos(tt * a2 * 0.23 + hsh(s, 7, 8) * 6.28)) * BH;
  const rad = (1.6 + hsh(s, 9, 8) * 2.6) * (0.6 + P.density * 0.9);
  const r2 = rad * rad;
  for (let j = Math.max(0, (cy - rad) | 0); j <= Math.min(BH - 1, (cy + rad) | 0); j++)
    for (let i = Math.max(0, (cx - rad) | 0); i <= Math.min(BW - 1, (cx + rad) | 0); i++) {
      const dx = i - cx, dy = j - cy, d2 = dx * dx + dy * dy;
      if (d2 > r2) continue;
      const w = (1 - d2 / r2) * 0.30;
      const p = j * BW + i;
      V[p] = Math.min(1.4, V[p] + w * 0.5); U[p] = Math.max(0, U[p] - w * 0.28);
    }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 11 + Math.sin(tt * 0.0181) * 17) % 360 + 360) % 360;
const gain = 0.5 + P.energy * 1.35 + A.rms * 0.4;
