    // the flow direction shades the filaments so the advection READS as motion
    const sxv = VX[p], syv = VY[p];
    const along = (gx * sxv + gy * syv) * 3.0;
    let r, gg, b;
    if (style === 'thermal') {
      const m = Math.min(1, (0.15 + uu2 * 0.06 + v * 0.68 + gm * 0.12) * (0.5 + P.energy * 0.85));
      r = Math.min(1, m * 2.15); gg = Math.min(1, Math.max(0, m * 2.0 - 0.55)); b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.4 - m * 1.5));
