      const d = 1 - v;
      const base = 0.04 + Math.pow(d, 1.9) * 0.46 * gain * 0.72;
      const rim = gm * gm * 0.6 * gain;
      r = base * 0.87 + rim * 0.9; gg = base * 0.95 + rim * 0.96; b = base * 1.05 + rim;
