      const ox2 = Math.pow(v, 0.8);
      const cc = pal(0.42 + ox2 * 0.1, 0.1, 0.0);
      const metal = 0.045 + (1 - ox2) * 0.30 * (0.4 + uu2 * 0.6);
      const speck = (hsh(i, j, 5) - 0.5) * 0.10 + (vn3(i * 0.5, j * 0.5, 3) - 0.5) * 0.22 * (0.3 + ox2);
      r = Math.min(1, metal * 1.25 + ox2 * cc[0] * 0.72 * gain * 0.7 + speck * 0.6);
      gg = Math.min(1, metal * 1.05 + ox2 * cc[1] * 0.95 * gain * 0.7 + speck * 0.6);
      b = Math.min(1, metal * 0.80 + ox2 * cc[2] * 0.80 * gain * 0.7 + speck * 0.5);
    } else if (style === 'graphite') {      // silky mono, form from the flow-aligned shading
      const s2 = 0.5 + along * 0.5;
      const val = 0.13 + uu2 * 0.05 + v * 0.16 + Math.max(0, s2 - 0.5) * 1.9 * (0.25 + gm * 2.2) * gain * 0.7 + gm * 0.30;
      r = Math.min(1, val * 1.02 + 0.03); gg = Math.min(1, val * 1.0 + 0.03); b = Math.min(1, val * 0.98 + 0.045);
    } else {                                // chemical (default) — vivid reagents streaming
      const cc = pal(0.06 + v * 0.5, 0.2, 0.0);
      const sub = pal(0.66, 0.13, 0.0);     // the unreacted substrate — the medium itself
      const gsh = (0.30 + uu2 * 0.24) * (0.7 + gain * 0.3);
      const vsh = (0.25 + v * 0.85) * (0.62 + gain * 0.42);
      const lit = 1 + along * 0.55;         // filaments catch light along the flow
      r = Math.min(1, (sub[0] * gsh * (1 - v * 0.8) + cc[0] * vsh * v * 1.3) * lit + v * v * 0.16);
      gg = Math.min(1, (sub[1] * gsh * (1 - v * 0.8) + cc[1] * vsh * v * 1.3) * lit + v * v * 0.14);
